     7	public class Reservation {
     8	    private final long id;
     9	    private final String roomNumber;
    10	    private final RoomType roomType;
    11	    private final GuestIdentification identification;
    12	    private final String guestEmail;
    13	    private final LocalDate checkIn;
    14	    private final LocalDate checkOut;
    15	    private final int guests;
    16	    private final RatePlan ratePlan;
    17	    private final int nights;
    18	    private final BigDecimal subtotal;
    19	    private final BigDecimal discount;
    20	    private final BigDecimal total;
    21	
    22	    private ReservationStatus status;
    23	    private BigDecimal amountPaid;
    24	    private BigDecimal refund;
    25	
    26	    public Reservation(long id, String roomNumber, RoomType roomType, GuestIdentification identification,
    27	                      String guestEmail, LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    28	        this.id = id;
    29	        this.roomNumber = roomNumber;
    30	        this.roomType = roomType;
    31	        this.identification = identification;
    32	        this.guestEmail = guestEmail;
    33	        this.checkIn = checkIn;
    34	        this.checkOut = checkOut;
    35	        this.guests = guests;
    36	        this.ratePlan = ratePlan;
    37	        this.status = ReservationStatus.PENDING;
    38	        this.amountPaid = BigDecimal.ZERO;
    39	        this.refund = null;
    40	
    41	        this.nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    42	        this.subtotal = calculateSubtotal();
    43	        this.discount = calculateDiscount();
    44	        this.total = subtotal.subtract(discount);
    45	    }
    46	
    47	    private BigDecimal calculateSubtotal() {
    48	        BigDecimal sum = BigDecimal.ZERO;
    49	        LocalDate date = checkIn;
    50	
    51	        while (date.isBefore(checkOut)) {
    52	            BigDecimal nightRate = roomType.getNightlyRate();
    53	            if (isHighSeason(date)) {
    54	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
    55	                    .setScale(2, RoundingMode.HALF_EVEN);
    56	            }
    57	            sum = sum.add(nightRate);
    58	            date = date.plusDays(1);
    59	        }
    60	
    61	        return sum.setScale(2, RoundingMode.HALF_EVEN);
    62	    }
    63	
    64	    private boolean isHighSeason(LocalDate date) {
    65	        int month = date.getMonthValue();
    66	        int day = date.getDayOfMonth();
    67	
    68	        if (month == 7) {
    69	            return true;
    70	        }
    71	
    72	        if (month == 12 && day >= 15) {
    73	            return true;
    74	        }
    75	
    76	        if (month == 1 || month == 2) {
    77	            return true;
    78	        }
    79	
    80	        return false;
    81	    }
    82	
    83	    private BigDecimal calculateDiscount() {
    84	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    85	            return subtotal.multiply(new BigDecimal("0.15"))
    86	                .setScale(2, RoundingMode.HALF_EVEN);
    87	        }
    88	        return BigDecimal.ZERO;
    89	    }
    90	
    91	    public void confirm() {
    92	        if (status != ReservationStatus.PENDING) {
    93	            throw new IllegalStateException("Cannot confirm reservation in status " + status);
    94	        }
    95	        this.status = ReservationStatus.CONFIRMED;
    96	        this.amountPaid = total;
    97	    }
    98	
    99	    public void checkIn() {
   100	        if (status != ReservationStatus.CONFIRMED) {
   101	            throw new IllegalStateException("Cannot check in reservation in status " + status);
   102	        }
   103	        this.status = ReservationStatus.CHECKED_IN;
   104	    }
   105	
   106	    public void checkOut() {
   107	        if (status != ReservationStatus.CHECKED_IN) {
   108	            throw new IllegalStateException("Cannot check out reservation in status " + status);
   109	        }
   110	        this.status = ReservationStatus.CHECKED_OUT;
   111	    }
   112	
   113	    public void cancel() {
   114	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
   115	            throw new IllegalStateException("Cannot cancel reservation in status " + status);
   116	        }
   117	
   118	        this.status = ReservationStatus.CANCELLED;
   119	
   120	        if (ratePlan == RatePlan.STANDARD && amountPaid.compareTo(BigDecimal.ZERO) > 0) {
   121	            this.refund = amountPaid;
   122	        } else {
   123	            this.refund = BigDecimal.ZERO;
   124	        }
