    15	            throw new IllegalStateException("Document can only be generated for paid reservations");
    16	        }
    17	
    18	        String title = getDocumentTitle(reservation);
    19	        String checkIn = reservation.getCheckIn().format(DATE_FORMATTER);
    20	        String checkOut = reservation.getCheckOut().format(DATE_FORMATTER);
    21	
    22	        return new Document(
    23	            title,
    24	            reservation.getId(),
    25	            reservation.getIdentification(),
    26	            reservation.getRoomNumber(),
    27	            reservation.getRoomType(),
    28	            checkIn,
    29	            checkOut,
    30	            reservation.getNights(),
    31	            reservation.getSubtotal(),
