    14	public class ReportService {
    15	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    16	
    17	    private final ReservationRepository reservationRepository;
    18	    private final RoomRepository roomRepository;
