    24	
    25	    public String generateOccupancyReport(LocalDate date) {
    26	        StringBuilder csv = new StringBuilder();
    27	        csv.append("room,type,reservation,check_in,check_out\n");
    28	
    29	        List<Reservation> occupiedReservations = reservationRepository.findAll().stream()
    30	            .filter(r -> r.isPaid())
    31	            .filter(r -> r.occupiesNight(date))
    32	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    33	            .toList();
    34	
    35	        for (Reservation reservation : occupiedReservations) {
    36	            csv.append(reservation.getRoomNumber()).append(",");
    37	            csv.append(reservation.getRoomType().name()).append(",");
    38	            csv.append(reservation.getId()).append(",");
    39	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    40	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
    41	        }
    42	
    43	        int totalRooms = roomRepository.findAll().size();
    44	        int occupiedRooms = occupiedReservations.size();
    45	        csv.append("total,").append(occupiedRooms).append("/").append(totalRooms);
    46	
    47	        return csv.toString();
    48	    }
    49	
    50	    public String generateRevenueReport(YearMonth month) {
    51	        StringBuilder csv = new StringBuilder();
    52	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    53	
    54	        LocalDate startOfMonth = month.atDay(1);
    55	        LocalDate endOfMonth = month.atEndOfMonth();
    56	
    57	        List<Reservation> reservations = reservationRepository.findAll().stream()
    58	            .filter(r -> !r.getCheckIn().isBefore(startOfMonth) && !r.getCheckIn().isAfter(endOfMonth))
    59	            .filter(r -> r.getNetAmount().compareTo(BigDecimal.ZERO) > 0)
    60	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    61	                .thenComparing(Reservation::getId))
    62	            .toList();
    63	
    64	        BigDecimal totalAmount = BigDecimal.ZERO;
    65	
    66	        for (Reservation reservation : reservations) {
    67	            BigDecimal netAmount = reservation.getNetAmount();
    68	            csv.append(reservation.getId()).append(",");
    69	            csv.append(reservation.getRoomNumber()).append(",");
    70	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    71	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    72	            csv.append(reservation.getStatus().name()).append(",");
    73	            csv.append(formatAmount(netAmount)).append("\n");
    74	
    75	            totalAmount = totalAmount.add(netAmount);
    76	        }
    77	
    78	        csv.append("total,").append(formatAmount(totalAmount));
    79	
    80	        return csv.toString();
    81	    }
    82	
    83	    private String formatAmount(BigDecimal amount) {
    84	        return amount.toString();
    85	    }
