    24	    public Reservation createReservation(String roomNumber, GuestIdentification identification,
    25	                                        String guestEmail, LocalDate checkIn, LocalDate checkOut,
    26	                                        int guests, RatePlan ratePlan) {
    27	        Room room = roomRepository.findByNumber(roomNumber)
    28	            .orElseThrow(() -> new RoomNotFoundException("Room not found"));
    29	
    30	        if (guests > room.getCapacity()) {
    31	            throw new CapacityExceededException("Room capacity exceeded");
    32	        }
    33	
    34	        if (guests < 1) {
    35	            throw new InvalidRequestException("At least one guest required");
    36	        }
    37	
    38	        LocalDate night = checkIn;
    39	        while (night.isBefore(checkOut)) {
    40	            List<Reservation> conflicting = reservationRepository.findByRoomAndNight(roomNumber, night);
    41	            if (!conflicting.isEmpty()) {
    42	                throw new RoomUnavailableException("Room already booked for selected dates");
    43	            }
    44	            night = night.plusDays(1);
    45	        }
    46	
    47	        long id = reservationRepository.nextId();
    48	        Reservation reservation = new Reservation(id, roomNumber, room.getType(), identification,
    49	            guestEmail, checkIn, checkOut, guests, ratePlan);
    50	
    51	        return reservationRepository.save(reservation);
    52	    }
