     8	public record CreateReservationRequest(
     9	    @JsonProperty("roomNumber") String roomNumber,
    10	    @JsonProperty("guestName") String guestName,
    11	    @JsonProperty("guestEmail") String guestEmail,
    12	    @JsonProperty("guestCpf") String guestCpf,
    13	    @JsonProperty("companyName") String companyName,
    14	    @JsonProperty("companyCnpj") String companyCnpj,
    15	    @JsonProperty("guestPassport") String guestPassport,
    16	    @JsonProperty("guestCountry") String guestCountry,
    17	    @JsonProperty("checkIn") LocalDate checkIn,
    18	    @JsonProperty("checkOut") LocalDate checkOut,
    19	    @JsonProperty("guests") Integer guests,
    20	    @JsonProperty("ratePlan") RatePlan ratePlan
    21	) {
    22	    public GuestIdentification toGuestIdentification() {
    23	        int identificationCount = 0;
    24	        GuestIdentification identification = null;
    25	
    26	        if (guestCpf != null) {
    27	            identificationCount++;
    28	            identification = new CpfIdentification(guestName, guestCpf);
    29	        }
    30	
    31	        if (companyCnpj != null && companyName != null) {
    32	            identificationCount++;
    33	            identification = new CnpjIdentification(guestName, companyName, companyCnpj);
    34	        }
    35	
    36	        if (guestPassport != null && guestCountry != null) {
    37	            identificationCount++;
    38	            identification = new PassportIdentification(guestName, guestPassport, guestCountry);
    39	        }
    40	
    41	        if (identificationCount != 1) {
    42	            throw new IllegalArgumentException("Exactly one identification method required");
    43	        }
    44	
    45	        return identification;
    46	    }
    47	
    48	    public void validate() {
    49	        if (roomNumber == null || guestName == null || guestEmail == null ||
    50	            checkIn == null || checkOut == null || guests == null || ratePlan == null) {
    51	            throw new IllegalArgumentException("Missing required fields");
    52	        }
    53	
    54	        if (!checkOut.isAfter(checkIn)) {
    55	            throw new IllegalArgumentException("Check-out must be after check-in");
    56	        }
    57	
    58	        if (guests < 1) {
    59	            throw new IllegalArgumentException("At least one guest required");
    60	        }
    61	
    62	        toGuestIdentification();
    63	    }
    64	}
